// Normalize the incoming webhook payload and build the LLM request.
const input = $input.first().json;
const body = input.body || {};
const query = input.query || {};

const message = String(body.message || '').trim().slice(0, 2000);

const systemPrompt = [
  'You are a lead-qualification assistant for a real-estate agency in Bengaluru, India.',
  'Classify one inbound enquiry as exactly one of: hot, warm, cold.',
  'hot  = clear intent to buy or rent within about 30 days AND at least one concrete signal',
  '       (stated budget, a specific property or locality, a site-visit or call request, loan or deposit ready).',
  'warm = genuine interest but no firm timeline or budget, or still comparing options, or asking for information.',
  'cold = no real purchase intent: just browsing, timeline longer than about 6 months, spam, vendor pitches,',
  '       job enquiries, wrong number, or unrelated requests.',
  'Return ONLY JSON: {"intent":"hot|warm|cold","score":<integer 0-100 purchase-readiness>,"reason":"<max 20 words>"}'
].join('\n');

return [{
  json: {
    lead_id: body.lead_id || ('L-' + Date.now()),
    name: body.name || '',
    email: body.email || '',
    phone: body.phone || '',
    source: body.source || 'website',
    message,
    dry_run: String(query.dry_run || '').toLowerCase() === 'true',
    received_at: new Date().toISOString(),
    started_at: Date.now(),
    // Change the model name here if Google retires it (check the Gemini API docs).
    llm_base_url: 'https://generativelanguage.googleapis.com/v1beta',
    model: 'gemini-2.5-flash',
    llm_body: {
      systemInstruction: { parts: [{ text: systemPrompt }] },
      contents: [{ role: 'user', parts: [{ text: message || '(empty message)' }] }],
      generationConfig: { temperature: 0, responseMimeType: 'application/json' }
    }
  }
}];

// Validate the LLM output. Anything unexpected falls back to 'warm' + needs_review
// so a human checks it instead of the lead being silently dropped.
const base = { ...$('Normalize').first().json };
delete base.llm_body;
const res = $input.first().json;

let out = { intent: 'warm', score: 50, reason: 'LLM unavailable or invalid output', needs_review: true };
try {
  const text = res.candidates[0].content.parts[0].text;
  const p = JSON.parse(text);
  const intent = String(p.intent || '').toLowerCase();
  if (['hot', 'warm', 'cold'].includes(intent)) {
    out = {
      intent,
      score: Math.max(0, Math.min(100, Math.round(Number(p.score) || 0))),
      reason: String(p.reason || '').slice(0, 200),
      needs_review: false
    };
  }
} catch (e) { /* keep fallback */ }

return [{ json: { ...base, ...out, latency_ms: Date.now() - base.started_at } }];

// Exactly the columns of the Google Sheet (see README).
const r = $('Parse Result').first().json;
return [{ json: {
  received_at: r.received_at, lead_id: r.lead_id, name: r.name, email: r.email,
  phone: r.phone, source: r.source, message: r.message, intent: r.intent,
  score: r.score, reason: r.reason, needs_review: r.needs_review, latency_ms: r.latency_ms
} }];
